'use strict';

/**
* Test whether an input value is a supported scale name.
*
* @module @stdlib/plot/vega/assert/is-scale
*
* @example
* var isScale = require( '@stdlib/plot/vega/assert/is-scale' );
*
* var bool = isScale( 'linear' );
* // returns true
*
* bool = isScale( 'log' );
* // returns true
*
* bool = isScale( 'ordinal' );
* // returns true
*
* bool = isScale( 'foo' );
* // returns false
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
